mapper.select:
SELECT * FROM ai_eval_dataset
owner_user_id = #{ownerUserId}
ORDER BY updated_at DESC LIMIT #{limit}

mapper.update:
UPDATE ai_eval_dataset_version
SET status='PUBLISHED', case_count=#{caseCount}, checksum=#{checksum}, published_at=#{publishedAt}
WHERE version_id=#{versionId} AND status='DRAFT'

UPDATE ai_eval_case SET stable_key=#{stableKey}, sequence_no=#{sequenceNo},
    conversation_group=#{conversationGroup}, category=#{category}, tags_json=#{tagsJson},
    question=#{question}, config_json=#{configJson}, reference_answer=#{referenceAnswer}, enabled=#{enabled}
WHERE case_id=#{caseId} AND version_id=#{versionId}

mapper.select:
SELECT * FROM ai_eval_case WHERE version_id=#{versionId}
AND enabled=1
ORDER BY conversation_group, sequence_no, id

SELECT * FROM ai_eval_run
dataset_id=#{datasetId}
ORDER BY created_at DESC LIMIT #{limit}

mapper.update:
UPDATE ai_eval_case_result
SET status='CANCELLED', finished_at=#{finishedAt}, error_message=#{errorMessage}
WHERE eval_run_id=#{evalRunId} AND status IN ('QUEUED','RUNNING')

mapper.select:
SELECT * FROM ai_eval_code_version
WHERE binding_status='WAITING_TAG'
ORDER BY created_at DESC LIMIT #{limit}

mapper.update:
UPDATE ai_eval_code_version SET binding_status=#{bindingStatus}, bound_tag=#{boundTag},
  bound_commit_sha=#{boundCommitSha}, matched_tags_json=#{matchedTagsJson},
  binding_method=#{bindingMethod}, binding_note=#{bindingNote}, bound_at=#{boundAt},
  last_checked_at=#{lastCheckedAt}
WHERE eval_run_id=#{evalRunId}

UPDATE ai_eval_judge_job SET status=#{status}, completed_cases=#{completedCases},
  failed_cases=#{failedCases}, average_score=#{averageScore}, finished_at=#{finishedAt}, error_message=#{errorMessage}
WHERE judge_job_id=#{judgeJobId} AND status<>'CANCELLED'

UPDATE ai_eval_judge_job
SET status='CANCELLED', finished_at=#{finishedAt}, error_message=#{errorMessage}
WHERE eval_run_id=#{evalRunId} AND status IN ('QUEUED','RUNNING')
